fn tolower(mut __c: i32) -> i32 {
    return if __c >= -(128 as i32) && __c < (256 as i32) {
        unsafe { *unsafe { unsafe { *unsafe { __ctype_tolower_loc() } }.offset(__c as isize) } }
    } else {
        __c
    };
}

