/// Look for the named VFS.  If it is a TRACEVFS, then unregister it
/// and delete it.
#[unsafe(no_mangle)]
extern "C-unwind" fn vfstrace_unregister(mut zTraceName: *const i8) {
    let mut pVfs: *mut sqlite3_vfs = unsafe { sqlite3_vfs_find(zTraceName) };
    if pVfs == std::ptr::null_mut::<sqlite3_vfs>() {
        return;
    }
    if (unsafe { (*pVfs).xOpen }) != Some(vfstraceOpen) {
        return;
    }
    unsafe { sqlite3_vfs_unregister(pVfs) };
    unsafe { sqlite3_free(pVfs as *mut ()) };
}

