/// Run zQuery.  Use dump_callback() as the callback routine so that
/// the contents of the query are output as SQL statements.
///
/// If we get a SQLITE_CORRUPT error, rerun the query after appending
/// "ORDER BY rowid DESC" to the end.
fn run_schema_dump_query(mut p: *mut ShellState, mut zQuery: *const i8) -> i32 {
    let mut rc: i32 = 0 as i32;
    let mut zErr: *mut i8 = std::ptr::null_mut::<i8>();
    rc = unsafe {
        sqlite3_exec(
            unsafe { (*p).db },
            zQuery,
            Some(dump_callback),
            p as *mut (),
            std::ptr::addr_of_mut!(zErr),
        )
    };
    if rc == (11 as i32) {
        let mut zQ2: *mut i8 = unsafe { std::mem::zeroed() };
        let mut len: i32 = strlen30(zQuery);
        cli_puts(
            (b"/****** CORRUPTION ERROR *******/\n\0".as_ptr() as *mut i8) as *const i8,
            unsafe { (*p).out },
        );
        if zErr != std::ptr::null_mut::<i8>() {
            unsafe {
                cli_printf(
                    unsafe { (*p).out },
                    (b"/****** %s ******/\n\0".as_ptr() as *mut i8) as *const i8,
                    zErr,
                )
            };
            unsafe { sqlite3_free(zErr as *mut ()) };
            zErr = std::ptr::null_mut::<i8>();
        }
        zQ2 = (unsafe { malloc(((len + (100 as i32)) as i64) as u64) }) as *mut i8;
        if zQ2 == std::ptr::null_mut::<i8>() {
            return rc;
        }
        unsafe {
            sqlite3_snprintf(
                len + (100 as i32),
                zQ2,
                (b"%s ORDER BY rowid DESC\0".as_ptr() as *mut i8) as *const i8,
                zQuery,
            )
        };
        rc = unsafe {
            sqlite3_exec(
                unsafe { (*p).db },
                zQ2 as *const i8,
                Some(dump_callback),
                p as *mut (),
                std::ptr::addr_of_mut!(zErr),
            )
        };
        if rc != (0 as i32) {
            unsafe {
                cli_printf(
                    unsafe { (*p).out },
                    (b"/****** ERROR: %s ******/\n\0".as_ptr() as *mut i8) as *const i8,
                    zErr,
                )
            };
        } else {
            rc = 11 as i32;
        }
        unsafe { free(zQ2 as *mut ()) };
    }
    unsafe { sqlite3_free(zErr as *mut ()) };
    return rc;
}

