fn usage(mut showDetail: i32) {
    unsafe {
        cli_printf(unsafe { stderr }, (b"Usage: %s [OPTIONS] [FILENAME [SQL...]]\nFILENAME is the name of an SQLite database. A new database is created\nif the file does not previously exist. Defaults to :memory:.\n\0".as_ptr() as *mut i8) as *const i8, unsafe { Argv0 })
    };
    if showDetail != (0 as i32) {
        unsafe {
            cli_printf(
                unsafe { stderr },
                (b"OPTIONS include:\n%s\0".as_ptr() as *mut i8) as *const i8,
                unsafe { std::ptr::addr_of!(zOptions.0) as *const i8 },
            )
        };
    } else {
        cli_puts(
            (b"Use the -help option for additional information\n\0".as_ptr() as *mut i8)
                as *const i8,
            unsafe { stderr },
        );
    }
    unsafe { exit(0 as i32) };
}

/// Internal check:  Verify that the SQLite is uninitialized.  Print a
/// error message if it is initialized.
fn verify_uninitialized() {
    if (unsafe { sqlite3_config(-(1 as i32)) }) == (21 as i32) {
        cli_puts(
            (b"WARNING: attempt to configure SQLite after initialization.\n\0".as_ptr() as *mut i8)
                as *const i8,
            unsafe { stdout },
        );
    }
}

/// Initialize the state information in data
fn main_init(mut p: *mut ShellState) {
    unsafe { memset(p as *mut (), 0 as i32, 4816 as u64) };
    unsafe {
        (*p).pAuxDb = unsafe {
            unsafe { (*p).aAuxDb.as_mut_ptr() as *mut AuxDb }.offset((0 as i32) as isize)
        };
    }
    unsafe {
        (*p).shellFlgs = (2 as i32) as u32;
    }
    unsafe {
        sqlite3_config(
            16 as i32,
            unsafe {
                std::mem::transmute::<
                    Option<unsafe extern "C-unwind" fn(*mut (), i32, *const i8)>,
                    *const u8,
                >(Some(shellLog))
            },
            p,
        )
    };
    verify_uninitialized();
    unsafe { sqlite3_config(17 as i32, 1 as i32) };
    unsafe { sqlite3_config(2 as i32) };
    unsafe {
        globalShellState = p;
    }
    // No \001...\002 escapes required for linenoise or when not using a
    // command-line editing library
    unsafe {
        (*p).bDelimitNonprint = ((0 as i32) as i8) as u8;
    }
}

/// Output text to the console in a font that attracts extra attention.
fn printBold(mut zText: *const i8) {
    if shellNoColor() != (0 as i32) {
        unsafe {
            cli_printf(
                unsafe { stdout },
                (b"%s\0".as_ptr() as *mut i8) as *const i8,
                zText,
            )
        };
    } else {
        unsafe {
            cli_printf(
                unsafe { stdout },
                (b"\x1b[1;36m\x1b[3m%s\x1b[0m\0".as_ptr() as *mut i8) as *const i8,
                zText,
            )
        };
    }
}

/// Get the argument to an --option.  Throw an error and die if no argument
/// is available.
fn cmdline_option_value(mut argc: i32, mut argv: *mut *mut i8, mut i: i32) -> *mut i8 {
    if i == argc {
        unsafe {
            cli_printf(
                unsafe { stderr },
                (b"%s: Error: missing argument to %s\n\0".as_ptr() as *mut i8) as *const i8,
                unsafe { *unsafe { argv.offset((0 as i32) as isize) } },
                unsafe { *unsafe { argv.offset((argc - (1 as i32)) as isize) } },
            )
        };
        cli_exit(1 as i32);
    }
    return unsafe { *unsafe { argv.offset(i as isize) } };
}

