extern "C-unwind" fn abnormalExit() {
    if (unsafe { std::ptr::read_volatile(std::ptr::addr_of!(seenInterrupt)) }) != (0 as i32) {
        cli_puts(
            (b"Program interrupted.\n\0".as_ptr() as *mut i8) as *const i8,
            unsafe { stderr },
        );
    }
    if (unsafe { globalShellState }) != std::ptr::null_mut::<ShellState>() {
        clearTempFile(unsafe { globalShellState }, 1 as i32, 1 as i32);
    }
}

